  docUrl.searchParams.set('version', PACKAGE_VERSION);
  docUrl.searchParams.set('code', serialized.code.toString());
  docUrl.searchParams.set('message', serialized.message);

  return {
    ...serialized,
    docUrl: docUrl.href,
  };
}

type ErrorResponse = {
  method: unknown;
  errorCode?: number;
  errorMessage: string;
};

