export function isMulticallSuccess<T = unknown>(
  result: MulticallResult<T>
): result is MulticallSuccess<T> {
  return result.status === 'success';
}

/**
 * Type guard to check if a multicall result is a failure
 *
 * @example
 * ```typescript
